import hashlib


class _Rules(Rules):
    """ObservationNoise (O axis, harder with DOSE): corrupt a deterministic fraction DOSE of the
    observation text by swapping characters in the grid/state rendering, without touching the
    underlying world. bucket = sha256(f"{task_id}:{step}")[:8] % 10000; corrupted iff bucket < DOSE*10000,
    so the corrupted step set is nested in DOSE. Solvable by construction (world untouched)."""

    DOSE = 0.75
    TASK_ID = '1'

    def _corrupted(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def filter_observation(self, obs, env_state):
        if not self._corrupted(env_state):
            return obs
        text = obs.text
        chars = list(text)
        for i in range(len(chars)):
            if chars[i].isdigit():
                chars[i] = str((int(chars[i]) + 1) % 10)
        return Observation(text="".join(chars), data=obs.data)

class _Rules(Rules):
    def filter_action(self, action, env_state):
        if action.name != "do":
            return action
        text = action.kwargs.get("text", "")
        # First navigation: force one retry.
        if text.startswith("go to ") and env_state.step_count == 0:
            if not env_state.extras.get("blocked_first_nav"):
                env_state.extras["blocked_first_nav"] = True
                return Blocked(reason="first navigation blocked to exercise recovery")
        # First open/examine of a closed receptacle: force one retry.
        if (text.startswith("open ") or text.startswith("examine ")) and not env_state.extras.get("blocked_first_open"):
            env_state.extras["blocked_first_open"] = True
            return Blocked(reason="first receptacle interaction blocked to exercise recovery")
        return action

class _Rules(Rules):
