import random

class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        # Occasionally strip the admissible-commands hint to force the
        # Policy to rely on its own memory / navigation rather than the
        # full command menu. Keeps env surface presentation unchanged
        # (text and other data intact); only the hint list is thinned.
        cmds = obs.data.get("admissible_commands")
        if not cmds:
            return obs
        # Deterministic per-episode: thin after a few steps to avoid
        # breaking the very first move.
        if env_state.step_count < 3:
            return obs
        # Thin roughly half the time once underway.
        if env_state.extras.get("thin_seed") is None:
            env_state.extras["thin_seed"] = random.random()
        if env_state.extras["thin_seed"] < 0.5:
            return obs
        # Keep only navigation commands, dropping examine/inventory hints
        # so the Policy must inspect rather than be told.
        kept = [c for c in cmds if not c.startswith("examine ")]
        if not kept:
            kept = cmds
        new_data = {**obs.data, "admissible_commands": kept}
        return Observation(text=obs.text, data=new_data)

class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        # Subtle O-axis nudge: when the policy is looping (repetition_count
        # high), append a gentle recovery hint to the observation text.
        # This exercises failure-recovery without changing the env surface.
        if env_state.repetition_count >= 2:
            hint = ("\n\nHint: you seem to be repeating yourself. "
                    "Re-check your inventory and the admissible commands.")
            return Observation(text=obs.text + hint, data=obs.data)
        return obs

class _Rules(Rules):
    def modify_transition(self, action, raw_response, env_state):
        # Only intervene when the Policy's action had no effect and it
        # appears stuck in a take/move loop. Inject a compact hint into
        # the observation text WITHOUT altering admissible commands or
        # bridge-set keys, keeping the env surface presentation intact.
        if not env_state.last_action_was_effective:
            obs = raw_response.observation
            hint = " (Hint: a soapbar must be clean before it can be placed; consider the sinkbasin.)"
            if "Hint:" not in obs.text:
                new_obs = Observation(text=obs.text + hint, data=obs.data)
                return EnvResponse(
                    observation=new_obs,
                    reward=raw_response.reward,
                    terminated=raw_response.terminated,
                    truncated=raw_response.truncated,
                    info=raw_response.info,
                )
        return raw_response

import random

class _Rules(Rules):
    def modify_transition(self, action, raw_response, env_state):
        # Only perturb at low frequency, and never on the final winning step
        if raw_response.info.get("won"):
            return raw_response
        text = action.kwargs.get("text", "")
        # Skip look/inventory/examine (harmless info-gathering) so we don't
        # starve the Policy of orientation; target movement/manipulation.
        if text.startswith(("look", "inventory", "examine")):
            return raw_response
        if random.random() < 0.08:
            new_obs = Observation(
                text="Nothing happens.",
                data=raw_response.observation.data,
            )
            return EnvResponse(
                observation=new_obs,
                reward=raw_response.reward,
                terminated=raw_response.terminated,
                truncated=raw_response.truncated,
                info=raw_response.info,
            )
        return raw_response

class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        # Narrowly perturb admissible commands: on a subset of steps,
        # drop a few non-essential 'examine <receptacle>' entries so the
        # policy must re-plan. Keep all 'go to', 'open', 'close', 'take',
        # 'put', 'heat', 'cool', 'clean', 'use' commands intact so the
        # task remains solvable.
        cmds = obs.data.get("admissible_commands")
        if not isinstance(cmds, list):
            return obs
        step = env_state.step_count
        # Only perturb on a sparse, deterministic subset of steps to avoid
        # making the task unsolvable.
        if step % 5 != 2:
            return obs
        kept = []
        for c in cmds:
            if c.startswith("examine ") and " plate" not in c and " sidetable" not in c:
                # drop some examine commands; keep plate/sidetable examines
                # which the goal-relevant objects rely on
                if len(c) % 2 == 0:
                    continue
            kept.append(c)
        if not kept:
            return obs
        return Observation(text=obs.text, data={**obs.data, "admissible_commands": kept})

import hashlib


class _Rules(Rules):
    """CommandSwap (O axis, harder with DOSE): corrupt the admissible-commands list by
    swapping a deterministic fraction DOSE of commands with near-miss strings. The world is
    untouched and the true command text remains recoverable by position/context, so the task
    stays solvable."""

    DOSE = 0.5
    TASK_ID = '23'

    def _perturbed(self, env_state):
        step = int(getattr(env_state, "step_count", 0) or 0)
        digest = hashlib.sha256(f"{self.TASK_ID}:{step}:swap".encode("utf-8")).hexdigest()
        return (int(digest[:8], 16) % 10000) < int(self.DOSE * 10000)

    def _swap(self, cmd):
        if cmd and cmd[0].islower():
            return cmd[0].upper() + cmd[1:]
        if cmd and cmd[0].isupper():
            return cmd[0].lower() + cmd[1:]
        return cmd

    def filter_observation(self, obs, env_state):
        if not self._perturbed(env_state):
            return obs
        data = dict(obs.data or {})
        cmds = data.get("admissible_commands")
        if isinstance(cmds, list) and cmds:
            data["admissible_commands"] = [self._swap(c) if isinstance(c, str) else c for c in cmds]
        return Observation(text=obs.text, data=data)

class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        # After the first step, drop the "Task: ..." goal line so the
        # Policy must remember the goal instead of re-reading it each turn.
        if env_state.step_count >= 1:
            lines = obs.text.splitlines()
            # Remove leading "Task: ..." and the blank line that follows it.
            kept = []
            skip = True
            for ln in lines:
                if skip:
                    if ln.startswith("Task:"):
                        continue  # drop the goal line
                    if ln.strip() == "":
                        continue  # drop the blank separator
                    skip = False
                kept.append(ln)
            new_text = "\n".join(kept)
            return Observation(text=new_text, data=obs.data)
        return obs

class _Rules(Rules):
    def filter_observation(self, obs, env_state):
        # Keep surface text identical; only prune admissible_commands to
        # reduce the Policy's wandering. Keep commands that mention
        # receptacles likely to hold the potato (fridge, microwave,
        # countertop, stove, sink) plus inventory/look/examine.
        cmds = obs.data.get("admissible_commands")
        if not isinstance(cmds, list):
            return obs
        keep_keywords = (
            "fridge", "microwave", "countertop", "stove", "sink",
            "inventory", "look", "examine", "cool", "potato",
        )
        pruned = [c for c in cmds if any(k in c for k in keep_keywords)]
        # Never empty the list entirely; fall back to original if pruned empty.
        if not pruned:
            pruned = cmds
        new_data = {**obs.data, "admissible_commands": pruned}
        return Observation(text=obs.text, data=new_data)
